package com.cnjava.book_store.Book;
import java.util.*; import org.springframework.stereotype.Service;
@Service public class BookServiceImp implements BookService { BookRepository bookRepository; public BookServiceImp(BookRepository bookRepository){this.bookRepository=bookRepository;} public List<Book> findAll(){return bookRepository.findAll();} public void createBook(Book b){bookRepository.save(b);} public Book getBookById(Long id){return bookRepository.findById(id).orElse(null);} public boolean deleteBookById(Long id){try{bookRepository.deleteById(id);return true;}catch(Exception e){return false;}} public boolean updateBook(Long id,Book u){Optional<Book> o=bookRepository.findById(id);if(o.isPresent()){Book b=o.get();b.setTitle(u.getTitle());b.setAuthor(u.getAuthor());b.setCategory(u.getCategory());b.setStock(u.getStock());b.setDescription(u.getDescription());b.setBook_cover(u.getBook_cover());bookRepository.save(b);return true;}return false;} }
